package extern

import (
	"strings"
	"testing"

	gfx "github.com/reoring/go4t/types"
)

func TestBindingBoundaries(t *testing.T) {
	var loader Loader
	pkg, err := loader.Load("github.com/reoring/go4t/extern/testdata/natural")
	if err != nil {
		t.Fatal(err)
	}
	withoutFloat := Bind(pkg, BindOptions{})
	for _, fragment := range []string{
		"// skipped: Alias (reserved go4t name alias; use --prefix)", "extern func aliasUnit(p0 Unit) Unit",
		"extern func strings(p0 List[String]) List[String]", "extern func ints(p0 List[Int]) List[Int]",
		"extern func optionInt(p0 Int, p1 Bool) Option[Int]", "extern func optionBool(p0 Bool, p1 Bool) Option[Bool]",
		"extern func withError(p0 String) IO[String]", "extern func stringsWithError(p0 List[String]) IO[List[String]]",
		"// skipped: Void (no result; Unit requires rt.Unit)", "// skipped: Float (unsupported parameter type float64)",
		"// skipped: Echo (unsupported parameter type any)", "// skipped: IO (unsupported parameter type github.com/reoring/go4t/rt.IO)",
		"// skipped: Named (unsupported parameter type github.com/reoring/go4t/extern/testdata/natural.NamedInt)",
		"// skipped: Type (reserved go4t name type; use --prefix)",
	} {
		if !strings.Contains(withoutFloat, fragment) {
			t.Errorf("missing %q in:\n%s", fragment, withoutFloat)
		}
	}
	withFloat := Bind(pkg, BindOptions{Float: true, Prefix: "native"})
	for _, fragment := range []string{
		"// Code generated by go4t bind github.com/reoring/go4t/extern/testdata/natural --prefix native.",
		"extern func nativeFloat(p0 Float) Float", "extern func nativeOptionFloat(p0 Float, p1 Bool) Option[Float]",
		"extern func nativeType() Int", "extern func nativeAlias(p0 Int) Int",
	} {
		if !strings.Contains(withFloat, fragment) {
			t.Errorf("missing %q in:\n%s", fragment, withFloat)
		}
	}
	for _, tc := range []struct {
		name  string
		typ   gfx.Type
		valid bool
	}{
		{"Alias", gfx.Int, true}, {"AliasUnit", gfx.Unit, true}, {"Named", gfx.Int, false},
	} {
		f, _ := pkg.Lookup(tc.name)
		_, err := Match(f, &gfx.TFunc{Params: []gfx.Type{tc.typ}, Ret: tc.typ})
		if (err == nil) != tc.valid {
			t.Errorf("Match(%s) = %v, valid=%v", tc.name, err, tc.valid)
		}
	}
}
